var L='en';
var TABS=['t1','t2','t3','t4','t5','t6'];
var curIdx=0;

var UNIVERSES=[
  {id:'halftone',en:'Halftone Classic',th:'คอมิกฮาล์ฟโทน',sw:'linear-gradient(135deg,#E23636,#2B6CE2)'},
