});

/* generic repeatable two-field row group */
function makeRowGroup(listId, addBtnId, namePh, descPh, namePhTh, descPhTh){
  var list=g(listId);
  function addRow(nameVal,descVal){
    var row=document.createElement('div');
    row.className='sv-rrow';
    row.innerHTML='<input class="sv-input rr-name" type="text" placeholder="'+(L==='th'?namePhTh:namePh)+'" value="'+(nameVal||'').replace(/"/g,'&quot;')+'">'+
      '<textarea class="sv-textarea rr-desc" placeholder="'+(L==='th'?descPhTh:descPh)+'">'+(descVal||'')+'</textarea>'+
      '<div class="sv-rdel">&times;</div>';
    row.querySelector('.sv-rdel').addEventListener('click',function(){row.remove()});
    list.appendChild(row);
  }
  g(addBtnId).addEventListener('click',function(){addRow('','')});
  return {addRow:addRow, list:list};
}
var powerGroup=makeRowGroup('sv-power-list','sv-power-add','Power name','What does it do?','ชื่อพลัง','ทำอะไรได้บ้าง?');
var gearGroup=makeRowGroup('sv-gear-list','sv-gear-add','Item name','What is it / does?','ชื่ออุปกรณ์','คืออะไร/ทำอะไร?');
