  row.className='sv-rrow';
  row.innerHTML='<input class="sv-input rr-name" type="text" placeholder="'+(L==='th'?'ชื่อ':'Name')+'" value="'+(nameVal||'').replace(/"/g,'&quot;')+'">'+
    '<input class="sv-input rr-desc" type="text" placeholder="'+(L==='th'?'ความสัมพันธ์':'Relationship')+'" value="'+(relVal||'').replace(/"/g,'&quot;')+'">'+
