});
function go(target){
  curIdx=TABS.indexOf(target);
  qa('.svtab').forEach(function(x){x.classList.toggle('on',x.getAttribute('data-t')===target)});
  qa('.svpanel').forEach(function(p){p.classList.toggle('on',p.getAttribute('data-p')===target)});
  g('sv-back').toggleAttribute('disabled',curIdx===0);
  g('sv-next').textContent=(curIdx===TABS.length-1)?(L==='th'?'ยืนยันตัวละคร':'Confirm Character'):(L==='th'?'ถัดไป':'Next');
}
g('sv-back').addEventListener('click',function(){if(curIdx>0)go(TABS[curIdx-1])});
g('sv-next').addEventListener('click',function(){
  if(curIdx<TABS.length-1){go(TABS[curIdx+1])}
  else{submit()}
});

function toast(msg){
  var el=g('sv-toast');el.textContent=msg;el.classList.add('show');
  setTimeout(function(){el.classList.remove('show')},2600);
}

function setLang(lang){
  L=lang;
  document.documentElement.setAttribute('lang-mode',lang);
  qa('#lg-en,#lg-th').forEach(function(b){b.classList.toggle('on',b.getAttribute('data-l')===lang)});
  qa('[data-en]').forEach(function(el){
    var v=lang==='th'?el.getAttribute('data-th'):el.getAttribute('data-en');
    if(v!=null)el.innerHTML=v;
  });
  qa('[data-pen]').forEach(function(el){
    var v=lang==='th'?el.getAttribute('data-pth'):el.getAttribute('data-pen');
    if(v!=null)el.setAttribute('placeholder',v);
  });
  go(TABS[curIdx]);
}
