function sendToST(text){
  try{
    var doc=(window.parent&&window.parent.document)?window.parent.document:document;
    var ta=doc.querySelector('#send_textarea')||doc.querySelector('textarea');
    if(ta){
      var setter=Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set;
      setter.call(ta,text);
      ta.dispatchEvent(new Event('input',{bubbles:true}));
      setTimeout(function(){
        var btn=doc.querySelector('#send_but');
        if(btn){btn.click();}
        else{
          ta.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',code:'Enter',keyCode:13,which:13,bubbles:true}));
        }
      },120);
      return true;
    }
  }catch(e){}
  try{navigator.clipboard.writeText(text)}catch(e2){}
  return false;
}

function readRows(listEl){
  return qa('.sv-rrow',listEl).map(function(row){
    return {name:row.querySelector('.rr-name').value.trim(),description:row.querySelector('.rr-desc').value.trim()};
  }).filter(function(x){return x.name||x.description});
}
function readTies(){
  return qa('.sv-rrow',tieList).map(function(row){
    return {name:row.querySelector('.rr-name').value.trim(),relationship:row.querySelector('.rr-desc').value.trim()};
  }).filter(function(x){return x.name||x.relationship});
}

