  var name=g('f-name').value.trim();
  if(!name){toast(L==='th'?'กรุณากรอกชื่อจริง':'Please enter a real name');go('t1');return;}

  var stdPowersOut=STDPOWERS.filter(function(x,i){return selStdPowers[i]}).map(function(x){return x[0]});

  var data={
