    name:name,
    age:g('f-age').value.trim(),
    persona:g('f-persona').value.trim(),
    appearance:g('f-appearance').value.trim(),
    earthDesignator:g('f-earth').value.trim(),
    universeStyle:selectedUni,
    universeDescription:g('f-unidesc').value.trim(),
    originStory:g('f-origin').value.trim(),
    standardPowers:stdPowersOut,
    uniquePowers:readRows(powerGroup.list),
    costume:g('f-costume').value.trim(),
    gear:readRows(gearGroup.list),
    connections:readTies(),
    standing:selectedStanding?selectedStanding[0]:'',
    canonEvent:g('f-canon').value.trim(),
    canonEventStatus:canonState,
    voice:g('f-voice').value.trim()
  };
  var txt='<SPIDERVERSE_DOSSIER>\n'+JSON.stringify(data)+'\n</SPIDERVERSE_DOSSIER>';
  var ok=sendToST(txt);
  toast(ok?(L==='th'?'ส่งข้อมูลตัวละครแล้ว...':'Character sent across the Verse...'):(L==='th'?'คัดลอกไปยังคลิปบอร์ดแล้ว':'Copied to clipboard'));
}
})();
